+// Sales from the till: each dish sold uses one portion of its recipe per
+// unit sold. A ticket is booked once; booking a set of sales is all or
+// nothing. The variance report compares that theoretical use with the
+// ledger's actual consumption.
+import { AppError } from "../errors.js";
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getItem, listItems, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been booked. */
+export function isTicketImported(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Books sales lines { row, ticket, soldAt, dishId, qty }; tickets booked
+ * before are skipped. Checks every line first (unknown dish: bad_request,
+ * short stock: sale_out_of_stock, both naming the row), then consumes the
+ * ingredients per ticket with ref `sale:<ticket>` at the sale time.
+ * Returns { tickets, dishes } counts of what was booked.
+ */
+export function bookSales(store, lines, { at }) {
+  const fresh = lines.filter((l) => !isTicketImported(store, l.ticket));
+  const planned = fresh.map((l) => {
+    const dish = (store.data.dishes ?? []).find((d) => d.id === l.dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `row ${l.row}: unknown dish ${l.dishId}` });
+    return { ...l, use: scaled(getRecipe(store, dish.recipeId), l.qty).filter((u) => u.qty > 0) };
+  });
+  const needed = new Map();
+  for (const p of planned) {
+    for (const u of p.use) {
+      const item = getItem(store, u.itemId);
+      const before = needed.get(u.itemId) ?? 0;
+      const total = round3(before + u.qty);
+      const stock = round3(onHand(store, u.itemId));
+      if (total > stock)
+        throw new AppError("sale_out_of_stock", { row: p.row, item: item.name, available: Math.max(0, round3(stock - before)), unit: item.unit });
+      needed.set(u.itemId, total);
+    }
+  }
+  const byTicket = new Map();
+  for (const p of planned) {
+    const list = byTicket.get(p.ticket) ?? [];
+    list.push(p);
+    byTicket.set(p.ticket, list);
+  }
+  store.data.sales ??= [];
+  let dishes = 0;
+  for (const [ticket, rows] of byTicket) {
+    const perItem = new Map();
+    for (const p of rows) {
+      store.data.sales.push({ id: store.nextId("sale"), ticket, soldAt: p.soldAt, dishId: p.dishId, qty: p.qty, use: p.use, importedAt: at });
+      dishes += p.qty;
+      for (const u of p.use) {
+        const cur = perItem.get(u.itemId) ?? { qty: 0, soldAt: p.soldAt };
+        perItem.set(u.itemId, { qty: round3(cur.qty + u.qty), soldAt: cur.soldAt });
+      }
+    }
+    for (const [itemId, { qty, soldAt }] of perItem) consume(store, itemId, qty, { at: soldAt, ref: `sale:${ticket}` });
+  }
+  return { tickets: byTicket.size, dishes };
+}
+
+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold in those days, actual use from every consume movement in those days,
+ * and difference = actual - theoretical. Items where both are zero are left out.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = dayOf(instant);
+    return day >= from && day <= to;
+  };
+  const theoretical = new Map();
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    for (const u of s.use) theoretical.set(u.itemId, (theoretical.get(u.itemId) ?? 0) + u.qty);
+  }
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId === undefined) continue;
+    actual.set(itemId, (actual.get(itemId) ?? 0) + m.qty);
+  }
+  return listItems(store)
+    .map((item) => {
+      const t = round3(theoretical.get(item.id) ?? 0);
+      const a = round3(actual.get(item.id) ?? 0);
+      return { itemId: item.id, name: item.name, unit: item.unit, theoretical: t, actual: a, difference: round3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
